    // Parse the JSON bytes into a serde_json::Value
    let value: Value = serde_json::from_slice(bytes)
        .map_err(|e| DocumentFormatError::MalformedPayload(e.into(), PayloadType::Json))?;

    // Serialize the value back to JSON with compact formatting
    let mut writer = write;
    serde_json::to_writer(&mut writer, &value)
        .map_err(DocumentFormatError::Io)?;

    // Return the number of bytes written (approximated by the serialized length)
    // Since we don't have direct access to the written count from the trait,
    // we calculate the length of the serialized JSON string.
    let serialized = serde_json::to_string(&value)
        .map_err(|e| DocumentFormatError::MalformedPayload(e.into(), PayloadType::Json))?;

    Ok(serialized.len() as u64)
}

