pub fn descending_facet_sort<'t>(
    rtxn: &'t heed::RoTxn<'t>,
    db: heed::Database<FacetGroupKeyCodec<BytesRefCodec>, FacetGroupValueCodec>,
    field_id: u16,
    candidates: RoaringBitmap,
) -> Result<impl Iterator<Item = Result<(RoaringBitmap, &'t [u8])>> + 't> {
    let mut stack = Vec::new();

    // Get the highest level to start from the top of the tree
    let highest_level = get_highest_level(rtxn, db, field_id)?;

    // Get the last (largest) facet value at level 0 to establish the upper bound
    let last_value = get_last_facet_value::<BytesRefCodec, _>(rtxn, db, field_id)?;

    if let Some(last_val) = last_value {
        // Create the initial range iterator for the highest level, starting from the end
        let mut level_prefix = Vec::new();
        level_prefix.extend_from_slice(&field_id.to_be_bytes());
        level_prefix.push(highest_level);

        let mut rev_iter = db
            .remap_types::<Bytes, DecodeIgnore>()
            .rev_prefix_iter(rtxn, &level_prefix)?;

        // We need to find the first entry at this level that is <= last_val
        // Since we are iterating backwards, we skip entries > last_val
        let mut first_valid = false;
        while let Some(entry) = rev_iter.next() {
            let (key_bytes, _) = entry?;
            let key = FacetGroupKeyCodec::<BytesRefCodec>::bytes_decode(key_bytes)
                .map_err(heed::Error::Decoding)?;

            // Compare the left_bound with last_val
            // We want entries where left_bound <= last_val
            if key.left_bound <= last_val {
                first_valid = true;
                break;
            }
        }

        if first_valid {
            // Reset iterator to the beginning of the range for this level
            // We need to create a new iterator that starts from the correct position
            // Since we can't easily seek in a rev_prefix_iter, we'll use a different approach:
            // Start from the very end and filter, or use a range.

            // Actually, let's use a range approach for better control
            let mut start_key = Vec::new();
            start_key.extend_from_slice(&field_id.to_be_bytes());
            start_key.push(highest_level);
            start_key.extend_from_slice(&last_val);

            // We want to iterate backwards from the end, but only include items <= last_val
            // The simplest way is to iterate backwards from the end of the level
            // and stop when we go below the minimum possible value for this level
            // But we need to filter by the candidates bitmap as well.

            // Let's restart with a cleaner approach:
            // Create a reverse iterator for the level, and we'll filter as we go
            let mut level_prefix = Vec::new();
            level_prefix.extend_from_slice(&field_id.to_be_bytes());
            level_prefix.push(highest_level);

            let rev_iter = db
                .remap_types::<Bytes, DecodeIgnore>()
                .rev_prefix_iter(rtxn, &level_prefix)?;

            // We need to take items that are <= last_val
            // Since we're iterating backwards, we start from the largest and go down
            // We'll use a custom iterator that filters
            let filtered_iter = rev_iter.take_while(|entry| {
                match entry {
                    Ok((key_bytes, _)) => {
                        let key = FacetGroupKeyCodec::<BytesRefCodec>::bytes_decode(key_bytes)
                            .map_err(|_| heed::Error::Decoding);
                        match key {
                            Ok(k) => k.left_bound <= last_val,
                            Err(_) => false,
                        }
                    }
                    Err(_) => false,
                }
            });

            stack.push((
                candidates.clone(),
                filtered_iter,
                Bound::Unbounded, // We'll handle the lower bound in the logic
            ));
        }
    }

    Ok(DescendingFacetSort {
        rtxn,
        db,
        field_id,
        stack,
    })
